import{_ as a,o as e,c as r,ah as i}from"./chunks/framework.DOn7345P.js";const f=JSON.parse('{"title":"2026-10-17","description":"","frontmatter":{},"headers":[],"relativePath":"2026-10/2026-10-17.md","filePath":"2026-10/2026-10-17.md","lastUpdated":1792918418000}'),n={name:"2026-10/2026-10-17.md"};function o(d,t,s,l,h,c){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="_2026-10-17" tabindex="-1">2026-10-17 <a class="header-anchor" href="#_2026-10-17" aria-label="Permalink to &quot;2026-10-17&quot;">​</a></h1><h2 id="机器狗-四足机器人" tabindex="-1">机器狗 / 四足机器人 <a class="header-anchor" href="#机器狗-四足机器人" aria-label="Permalink to &quot;机器狗 / 四足机器人&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标题</th><th>arXiv分类</th><th>作者</th><th>发布日期</th><th>PDF</th><th>摘要</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2610.24895v1" target="_blank" rel="noreferrer">Anticipatory Gait Switching for Quadrupeds via Look-Ahead MDP Planning</a></td><td>cs.RO - Robotics</td><td>Kelvin Aladum, Justin Peel, Nisar Ahmed</td><td>2026-10-17</td><td><a href="https://arxiv.org/pdf/2610.24895v1.pdf" target="_blank" rel="noreferrer">下载</a></td><td>Quadruped robots often switch gaits to traverse mixed terrain safely. Many practical supervisors enforce hardware constraints (e.g., dwell or guard intervals) using a transition handler.</td></tr><tr><td><a href="https://arxiv.org/abs/2610.24847v1" target="_blank" rel="noreferrer">DiPLO: Self-distilled Diffusion Planning for Loco-manipulation</a></td><td>cs.RO - Robotics</td><td>Shafeef Omar, Sebastian Sanokowski, Elham Daneshmand, Dian Yu, Daniel Cremers, Cordelia Schmid, Majid Khadiv</td><td>2026-10-17</td><td><a href="https://arxiv.org/pdf/2610.24847v1.pdf" target="_blank" rel="noreferrer">下载</a></td><td>Humanoid loco-manipulation is particularly challenging because it requires coordinating locomotion, balance, and object interaction, making it difficult to learn from limited demonstrations or from scratch through Reinforcement Learning (RL).</td></tr><tr><td><a href="https://arxiv.org/abs/2610.24675v1" target="_blank" rel="noreferrer">Action-Aligned Latent Planning for Versatile Humanoid Loco-Manipulation</a></td><td>cs.RO - Robotics</td><td>Yutang Lin, Guanya Shi, C. Karen Liu</td><td>2026-10-17</td><td><a href="https://arxiv.org/pdf/2610.24675v1.pdf" target="_blank" rel="noreferrer">下载</a></td><td>Learning a single perceptive policy for diverse humanoid loco-manipulation requires unifying high-level task decisions without losing the state-dependent physical responses that make each interaction succeed.</td></tr><tr><td><a href="https://arxiv.org/abs/2610.24610v1" target="_blank" rel="noreferrer">Solving a Giant Rubik&#39;s Cube with a Quadruped Robot</a></td><td>cs.RO - Robotics</td><td>Lukas Amiet, Gabriel Sánchez-Blanco Repgen, Mayank Mittal, Victor Klemm, Andrei Cramariuc, Marco Hutter, Cesar Cadena</td><td>2026-10-17</td><td><a href="https://arxiv.org/pdf/2610.24610v1.pdf" target="_blank" rel="noreferrer">下载</a></td><td>Pedipulating a freestanding articulated object requires controlling its pose and internal configuration while maintaining balance. We demonstrate this capability by autonomously solving a giant Rubik&#39;s Cube with a quadruped using only its feet.</td></tr></tbody></table>',3)])])}const p=a(n,[["render",o]]);export{f as __pageData,p as default};
